","source/Infrastructure/RequestIdentity.cs":"using System.Security.Claims;
using StudentManagement.Core;
namespace StudentManagement.Web;
public sealed class RequestIdentity(IHttpContextAccessor accessor)
{
    private HttpContext Context => accessor.HttpContext ?? throw new InvalidOperationException("HTTP要求がありません。");
    public CurrentUser CurrentUser {
        get { var p=Context.User; if(p.Identity?.IsAuthenticated!=true) throw new WebFault(401,"認証が失効しました。再認証してください。");
            var id=p.FindFirstValue(ClaimTypes.NameIdentifier); var session=p.FindFirstValue("login_session"); var role=p.FindFirstValue(ClaimTypes.Role);
            if(string.IsNullOrWhiteSpace(id)||id.EnumerateRunes().Count()>64||string.IsNullOrWhiteSpace(session)||session.Length>64||!Enum.TryParse<Role>(role,out var r)) throw new WebFault(401,"認証情報を確認できません。"); return new(id,session,r); }
    }
    public string TabId => Context.Request.Headers["X-Tab-Id"].FirstOrDefault() ?? Context.Request.Query["tabId"].FirstOrDefault() ?? "";
    public void Read() { _=CurrentUser; }
    public void CreateOrUpdate() { if(CurrentUser.Role==Role.Viewer) throw new WebFault(403,"この操作を実行する権限がありません。"); }
    public void Administrator() { if(CurrentUser.Role!=Role.Administrator) throw new WebFault(403,"管理者権限が必要です。"); }
    public object Permissions => new { read=true,create=CurrentUser.Role!=Role.Viewer,update=CurrentUser.Role!=Role.Viewer,@delete=CurrentUser.Role==Role.Administrator,maintain=CurrentUser.Role==Role.Administrator };
}
public sealed class WebFault(int status,string message,string? field=null,string messageId="E-COM-004") : Exception(message) { public int Status {get;}=status; public string? Field {get;}=field; public string MessageId {get;}=messageId; }
","source/Infrastructure/WebStudentCoordinator.cs":"using StudentManagement.Core;
namespace StudentManagement.Web;
public sealed class WebStudentCoordinator(IStudentService service,RequestIdentity identity,SearchContextStore contexts)
{
    public SearchContextStore.Entry NewContext(string? tab=null)=>contexts.Create(identity.CurrentUser,tab);
    public void CheckReturn(string? id) { if(!string.IsNullOrEmpty(id)) contexts.Get(id,identity.CurrentUser); }
    public async Task<object> Search(SearchRequest request,string? tab,CancellationToken ct) {
        identity.Read(); var criteria=request.Criteria.ToCriteria(request.PageSize,request.SortKey,request.SortDirection);
        return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result; entry.Revision++; return Present(entry,result); },ct);
    }
    public async Task<object> Page(PageRequest request,string? tab,CancellationToken ct) {
        identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) throw new WebFault(409,"先に検索してください。"); var criteria=SearchContextStore.Copy(entry.Applied); criteria.Page=criteria.PageSize!=request.PageSize||criteria.SortKey!=request.SortKey||criteria.SortDirection!=request.SortDirection?1:request.Page; criteria.PageSize=request.PageSize; criteria.SortKey=request.SortKey;criteria.SortDirection=request.SortDirection; var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); if(!result.LimitExceeded&&criteria.Page>Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize)) { criteria.Page=Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize);result=await service.SearchAsync(criteria,ct);EnsureSearch(result); } entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct);
    }
    public async Task<object> Resume(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) return Present(entry,null); var result=await service.SearchAsync(entry.Applied,ct);EnsureSearch(result);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct); }
    public Task<object> Clear(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return contexts.Use(request,identity.CurrentUser,tab,entry=> { entry.Applied=null;entry.LastResult=null;entry.Revision++;return Task.FromResult(Present(entry,null)); },ct); }
    public async Task<object> Options(OptionsRequest request,CancellationToken ct) { identity.Read(); if(request.Usage=="register") identity.CreateOrUpdate(); StudentDetail? existing=null; if(!string.IsNullOrEmpty(request.StudentId)) existing=await service.GetAsync(IdParser.Required(request.StudentId,"REG-INT-012"),ct) ?? throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103"); return WebPresentation.Lookups(await service.LookupAsync(request.Usage=="register",ct),request.Usage,existing,request.SchoolYear,request.GradeCode,request.EnrollmentStatusCode,request.AdmissionDate,request.EnrollmentEndDate); }
    public async Task<(StudentDetail? Detail,StudentSaveInput Form,LookupSet Lookups)> Edit(long? id,string? contextId,CancellationToken ct) { identity.Read();CheckReturn(contextId); if(id is null) identity.CreateOrUpdate(); var detail=id is null?null:await service.GetAsync(id.Value,ct)??throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103");var lookup=await service.LookupAsync(ct);return(detail,StudentSaveInput.From(detail,contextId,lookup),lookup); }
    public async Task<SaveResult> Save(long? id,StudentSaveInput input,CancellationToken ct) { identity.CreateOrUpdate();CheckReturn(input.ReturnContextId); return await service.SaveAsync(input.ToRequest(id),ct); }
    public async Task<SaveResult> Delete(long id,StudentDeleteInput input,CancellationToken ct) { identity.Administrator(); CheckReturn(input.ReturnContextId);if(!input.Confirmed) throw new WebFault(422,"削除対象と理由を確認してください。","REG-026");return await service.DeleteAsync(id,IdParser.Required(input.ExpectedVersion,"REG-INT-013"),input.Reason,ct); }
    private static void EnsureSearch(SearchResult result) { if(result.Outcome is not (Outcome.Saved or Outcome.NoChange)) { var error=result.Errors.FirstOrDefault();throw new WebFault(WebPresentation.Status(result.Outcome),error?.Message??"検索できませんでした。",error?.Field,error?.Code??"E-COM-004"); } }
    public static object Present(SearchContextStore.Entry entry,SearchResult? result) { var c=entry.Applied??new SearchCriteria(); return new { outcome=result is null?"unsearched":result.LimitExceeded?"tooMany":result.Count==0?"empty":"found",totalCount=result is null||result.LimitExceeded?(int?)null:result.Count,items=(result?.Items??[]).Select(WebPresentation.Row),page=c.Page,pageSize=c.PageSize,sortKey=c.SortKey,sortDirection=c.SortDirection,searchedAt=result is null?null:WebPresentation.Time(result.SearchedAt),contextId=entry.Id,contextRevision=entry.Revision.ToString(System.Globalization.CultureInfo.InvariantCulture),criteria=new { studentNo=c.StudentNo??"",name=c.StudentName??"",kana=c.StudentNameKana??"",c.SchoolYear,c.GradeCode,classId=c.ClassId?.ToString(System.Globalization.CultureInfo.InvariantCulture),c.UnassignedOnly,statusCodes=c.EnrollmentStatusCodes,c.PrefectureCode,phoneNumber=c.PhoneNumber??"",c.AdmissionFrom,c.AdmissionTo } }; }
}
